### C++

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
using namespace std;

string solve(int d, string s) {
    int n = s.size();

    // 提取下标为 d 的倍数的字符（下标从1开始）
    vector<char> dChars;
    for (int i = d - 1; i < n; i += d) {
        dChars.push_back(s[i]);
    }

    // 提取下标不是 d 的倍数的字符
    vector<char> nonDChars;
    for (int i = 0; i < n; ++i) {
        if ((i + 1) % d != 0) {
            nonDChars.push_back(s[i]);
        }
    }

    // 对 d 倍数位置字符升序排序
    sort(dChars.begin(), dChars.end());
    // 对非 d 倍数位置字符降序排序
    sort(nonDChars.rbegin(), nonDChars.rend());

    // 初始化结果字符串
    vector<char> result(s.begin(), s.end());

    // 将排序后的 d 倍数位置字符放回
    int dIdx = 0;
    for (int i = d - 1; i < n; i += d) {
        result[i] = dChars[dIdx++];
    }

    // 将排序后的非 d 倍数位置字符放回
    int nonDIdx = 0;
    for (int i = 0; i < n; ++i) {
        if ((i + 1) % d != 0) {
            result[i] = nonDChars[nonDIdx++];
        }
    }

    return string(result.begin(), result.end());
}

int main() {
    int d;
    string s;
    cin >> d >> s;
    cout << solve(d, s) << endl;
    return 0;
}
